 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+  
+  while (pos < template.length) {
+    // Look for the next tag start
+    const nextOpen = template.indexOf('{{', pos);
+    
+    // If no more tags, add remaining text and break
+    if (nextOpen === -1) {
+      if (pos < template.length) {
+        tokens.push({ kind: "text", text: template.slice(pos) });
+      }
+      break;
+    }
+    
+    // Add text before the tag
+    if (nextOpen > pos) {
+      tokens.push({ kind: "text", text: template.slice(pos, nextOpen) });
+    }
+    
+    // Check if it's a triple brace (raw value)
+    if (template[nextOpen + 2] === '{') {
+      // Triple brace: {{{ ... }}}
+      const end = template.indexOf('}}}', nextOpen + 3);
+      if (end === -1) {
+        throw new Error("unterminated tag");
+      }
+      
+      const content = template.slice(nextOpen + 3, end).trim();
+      if (content.startsWith('#if ')) {
+        const path = content.slice(4).trim();
+        tokens.push({ kind: "if", path });
+      } else if (content === 'else') {
+        tokens.push({ kind: "else" });
+      } else if (content === '/if') {
+        tokens.push({ kind: "end" });
+      } else {
+        tokens.push({ kind: "value", expr: content, raw: true });
+      }
+      
